Lemma lp_B : forall (fx : FPState) regs (m : word -> option byte) (s pix h lines wpl data : Z),
  (4096 + 32 <= s <= 2 ^ 47)%Z ->
  (4096 <= pix)%Z ->
  (pix + 64 <= 2 ^ 47)%Z ->
  (1 <= h <= 20000)%Z ->
  (4096 <= lines)%Z ->
  (lines + 8 * h <= 2 ^ 47)%Z ->
  (0 <= wpl < 2 ^ 31)%Z ->
  (0 <= data < 2 ^ 47)%Z ->
  rdn SEGS m (Z_to_bv 64 (pix + 16)) 4 = Some (Z_to_le_bytes 4 wpl) ->
  rdn SEGS m (Z_to_bv 64 (pix + 56)) 8 = Some (Z_to_le_bytes 8 data) ->
  getr regs 2 = Z_to_bv 64 (s - 32) ->
  getr regs 10 = Z_to_bv 64 lines ->
  getr regs 8 = Z_to_bv 64 pix ->
  getr regs 9 = Z_to_bv 64 h ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 107628) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 107660) M' rom /\
      M' = m /\ getr regs' 10 = Z_to_bv 64 lines /\ getr regs' 11 = Z_to_bv 64 data /\ getr regs' 12 = Z_to_bv 64 (4 * wpl) /\
      getr regs' 13 = Z_to_bv 64 (lines + 8 * h) /\ getr regs' 14 = Z_to_bv 64 lines /\ regs_agree (fun r => In r [11; 12; 13; 14]%list) regs regs').
Proof.
