(* [comment removed for export] *)
Definition lp_rows (M : word -> option byte) (lines data W4 k : Z) : Prop :=
  forall i, (0 <= i < k)%Z -> rdn SEGS M (Z_to_bv 64 (lines + 8 * i)) 8 = Some (Z_to_le_bytes 8 (data + W4 * i)).

Lemma lp_loop : forall (n : nat) (fx : FPState) regs (M0 M : word -> option byte) (lines data W4 h i : Z),
  Z.of_nat n = (h - i)%Z -> (0 <= i < h)%Z -> (h <= 20000)%Z -> (4096 <= lines)%Z -> (lines + 8 * h <= 2 ^ 47)%Z -> (0 <= data)%Z -> (0 <= W4 <= 2 ^ 33)%Z -> (data + W4 * h <= 2 ^ 48)%Z ->
  store_ok SEGS M0 (Z_to_bv 64 lines) (Z.to_nat (8 * h)) = true -> rinv [(lines, (8 * h)%Z)] M0 M -> lp_rows M lines data W4 i ->
  getr regs 14 = Z_to_bv 64 (lines + 8 * i) -> getr regs 11 = Z_to_bv 64 (data + W4 * i) -> getr regs 12 = Z_to_bv 64 W4 -> getr regs 13 = Z_to_bv 64 (lines + 8 * h) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 0x1a48c) M rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 0x1a49c) M' rom /\ rinv [(lines, (8 * h)%Z)] M0 M' /\ lp_rows M' lines data W4 h /\
                regs_agree (fun r => In r [11; 14]%list) regs regs').
Proof.
